def solve(grid):
    """Count the number of islands (connected components of 1s) in a 2D grid.
    Cells are connected orthogonally (up, down, left, right).
    The grid may be empty or have rows of varying lengths; we treat missing cells as 0.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = max((len(row) for row in grid), default=0)
    visited = [[False] * cols for _ in range(rows)]

    def get_val(r, c):
        # Return cell value if within the row length, else 0
        if 0 <= r < rows and 0 <= c < len(grid[r]):
            return grid[r][c]
        return 0

    def dfs(start_r, start_c):
        stack = [(start_r, start_c)]
        while stack:
            r, c = stack.pop()
            if r < 0 or r >= rows or c < 0 or c >= len(grid[r]):
                continue
            if visited[r][c] or grid[r][c] == 0:
                continue
            visited[r][c] = True
            stack.extend([(r-1, c), (r+1, c), (r, c-1), (r, c+1)])

    islands = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if not visited[i][j] and grid[i][j] == 1:
