def solve(tokens):
    """Evaluate Reverse Polish Notation tokens with integer arithmetic.
    Operators supported: +, -, *, /. Division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division truncating toward zero without float
                # Compute absolute division and apply sign
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                res = abs(a) // abs(b)
                if (a < 0) ^ (b < 0):
                    res = -res
                stack.append(res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

